CREATE TABLE "menus" (
	"id" smallint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "menus_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 32767 START WITH 1 CACHE 1),
	"parent_id" smallint,
	"name" varchar NOT NULL,
	"label" varchar NOT NULL,
	"type" smallint NOT NULL,
	"route" varchar,
	"icon" varchar,
	"active" boolean DEFAULT true,
	"order" smallint,
	"component" varchar,
	"hide" boolean DEFAULT false,
	"hideTab" boolean DEFAULT false,
	"frameSrc" varchar,
	"newFeature" boolean DEFAULT false,
	"created_at" timestamp DEFAULT now(),
	"updated_at" timestamp DEFAULT now()
);

CREATE TABLE "roles" (
	"id" "smallserial" PRIMARY KEY NOT NULL,
	"name" varchar,
	"desc" varchar,
	"status" boolean DEFAULT true,
	"menus" smallint[] DEFAULT '{}',
	"hmenus" smallint[] DEFAULT '{}',
	"apis" bigint[] DEFAULT '{}',
	"created_at" timestamp DEFAULT now(),
	"updated_at" timestamp DEFAULT now()
);

CREATE TABLE "users" (
	"id" bigserial PRIMARY KEY NOT NULL,
	"email" varchar,
	"username" varchar DEFAULT '',
	"avatar" varchar DEFAULT '',
	"status" boolean DEFAULT true,
	"hpass" varchar,
	"salt" varchar,
	"roles" smallint[] DEFAULT '{}',
	"created_at" timestamp DEFAULT now(),
	"updated_at" timestamp DEFAULT now(),
	CONSTRAINT "users_email_unique" UNIQUE("email")
);

ALTER TABLE "menus" ADD CONSTRAINT "menus_parent_id_menus_id_fk" FOREIGN KEY ("parent_id") REFERENCES "public"."menus"("id") ON DELETE no action ON UPDATE no action;